package com.marketplace.productservice;
import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.data.mongodb.repository.MongoRepository; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.time.Instant; import java.util.*;
interface ReviewRepository extends MongoRepository<Review,String>{List<Review> findByProductIdOrderByCreatedAtDesc(Long productId);}@RestController @RequestMapping("/api/products/{productId}/reviews") class ReviewController{private final ReviewRepository reviews;ReviewController(ReviewRepository r){reviews=r;}record Request(@NotNull @Positive Long customerId,@Min(1) @Max(5) int rating,@NotBlank @Size(max=2000) String comment){}@GetMapping List<Review> list(@PathVariable Long productId){return reviews.findByProductIdOrderByCreatedAtDesc(productId);}@PostMapping ResponseEntity<Review> create(@PathVariable Long productId,@Valid @RequestBody Request r){var review=reviews.save(new Review(null,productId,r.customerId(),r.rating(),r.comment(),Instant.now()));return ResponseEntity.status(HttpStatus.CREATED).body(review);}}
